#include <stdio.h>
#include <stdlib.h>
int LLVMFuzzerInitialize(int *argc, char ***argv);
int LLVMFuzzerTestOneInput(const char *data, size_t size);
int main(int argc, char **argv){
  FILE *f; long n; char *buf;
  LLVMFuzzerInitialize(&argc, &argv);
  if(argc < 2) return 2;
  f=fopen(argv[1],"rb"); if(!f) return 3;
  fseek(f,0,SEEK_END); n=ftell(f); fseek(f,0,SEEK_SET);
  buf=(char*)malloc(n? n:1); if(!buf) return 4;
  if(n && fread(buf,1,n,f)!=(size_t)n) return 5;
  fclose(f);
  return LLVMFuzzerTestOneInput(buf,(size_t)n);
}
EOF
./libtool --mode=compile gcc -DHAVE_CONFIG_H -I. -I./include -g -O0 -c fuzz/xml.c -o fuzz/xml.o
