./libtool --mode=compile gcc -DHAVE_CONFIG_H -I. -I./include -g -O0 -c fuzz/driver.c -o fuzz/driver.o
./libtool --mode=link gcc -g -O0 -o fuzz/xml fuzz/xml.o fuzz/fuzz.o fuzz/driver.o .libs/libxml2.la -lz -llzma -lm
ls -l fuzz/xml .libs/libxml2.so'

